// Parser Mercasa central portal — sin dependencias externas (regex only)
// n8n runner externo bloquea require('cheerio') asi que parseamos con regex
const html = $input.first().json.data
const hoy = new Date().toISOString().split('T')[0]

const MERCAS = ['mercamadrid', 'mercabarna', 'mercabilbao', 'mercavalencia', 'mercasevilla']
const CATEGORIAS = ['Frutas', 'Hortalizas', 'Pescado Fresco', 'Pescado Congelado', 'Carnes']

const tableMatch = html.match(/<table[^>]*>([\s\S]*?)<\/table>/)
if (!tableMatch) throw new Error('No se encontro tabla en el HTML')
const tableHtml = tableMatch[1]

function stripTags(s) {
  return s.replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim()
}

const items = []
let currentCat = null
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/g
let rowMatch

while ((rowMatch = rowRegex.exec(tableHtml)) !== null) {
  const cells = []
  const cellRegex = /<t[hd][^>]*>([\s\S]*?)<\/t[hd]>/g
  let cellMatch
  while ((cellMatch = cellRegex.exec(rowMatch[1])) !== null) {
    cells.push(stripTags(cellMatch[1]))
  }
  if (cells.length === 0) continue

  if (cells.length === 1 && CATEGORIAS.includes(cells[0])) {
    currentCat = cells[0]
    continue
  }
  if (cells[0] === 'Productos' || /^\d{1,2}\/\d{1,2}$/.test(cells[0])) continue
  if (cells.length !== 11) continue

  const producto = cells[0]
  if (!producto || producto.length < 2) continue

  MERCAS.forEach((merca, mi) => {
    const raw = cells[1 + mi * 2 + 1]
    if (!raw || raw === '' || raw === '-') return
    const precio = parseFloat(raw.replace(',', '.'))
    if (!Number.isFinite(precio) || precio <= 0) return
    items.push({
      json: {
        producto_scraper: producto,
        categoria: currentCat,
        mercado_slug: merca,
        precio_kg: precio,
        fecha: hoy
      }
    })
  })
}

if (items.length === 0) throw new Error('Parser no extrajo ningun precio')
return items

// Construye el registro de precio con IDs de mercado hardcodeados (poblados al crear la base)
const MERCADO_IDS = {
  mercabarna: 'recLy7kRK4US0OMAp',
  mercamadrid: 'recxOTy49LL6j7kgL',
  mercavalencia: 'recKPDMam37kiVYwA',
  mercabilbao: 'rec2q8E6OICBjFhzN',
  mercasevilla: 'recLr4elsMTrhQu2R'
}

const ing = $input.first().json                                     // ingrediente Airtable
const scraper = $('Code · parser Mercasa').item.json                // datos scraper

const mercadoId = MERCADO_IDS[scraper.mercado_slug]
if (!mercadoId) throw new Error('Mercado desconocido: ' + scraper.mercado_slug)

const idRegistro = `${ing.id}-${mercadoId}-${scraper.fecha}`

return [{
  json: {
    id_registro: idRegistro,
    fecha: scraper.fecha,
    precio_kg: scraper.precio_kg,
    unidad: 'kg',
    procedencia_scraper: 'n8n_mercasa_central',
    ingrediente: [ing.id],
    mercado: [mercadoId]
  }
}]
